      "action": "GENERALIZE",
      "replacement": "l'impresa interessata",
      "reason": "La denominazione dell'impresa può essere ricondotta al suo ruolo nella verifica senza mantenere l'identificativo dell'organizzazione."
    },
    {
      "detection_id": "det_4c6e790817a5effb",
      "action": "GENERALIZE",
      "replacement": "la società acquirente",
      "reason": "La funzione della società nell'operazione societaria è pertinente, mentre il nome specifico non è necessario."
    },
    {
      "detection_id": "det_da8ea1b0066755c4",
      "action": "MASK",
      "replacement": "[NOME REDATTO]",
      "reason": "È la ripetizione del nome identificativo del mittente riportata dall'agente e va rimossa integralmente."
    },
    {
      "detection_id": "det_cac6df80e0e49ffe",
      "action": "MASK",
      "replacement": "[EMAIL REDATTA]",
      "reason": "È la ripetizione di un recapito email identificativo e va rimossa integralmente."
    }
